Fonction sci_vers_decimal(m, e):
    // m : mantisse, e : exposant entier
    si e ≥ 0 alors
        // Décaler la virgule vers la droite de e positions
        résultat ← m * 10^e
    sinon
        // Décaler la virgule vers la gauche de |e| positions
        résultat ← m / 10^|e|
    fin si
    retourner résultat

Algorithme simplifier_expression(m, n, p, q):
    // Calcul de l'exposant final k
    // (a^m)^n = a^{m*n}
    // a^{m*n} * a^p = a^{m*n + p}
    // division par a^q : soustraire q
    k ← m * n + p - q
    afficher "L'expression se simplifie en a^" + k
    retourner k
